# Extract all surplus/deficit data from 1989-2013 from the various page files
# and then find any 2025 estimate from the U.S. Treasury

# Data from treasury_bulletin_1994_06_page_28.txt (1989-1994)
data_1994 = {
    1989: -152087,
    1990: -220388,
    1991: -268729,
    1992: -290204,
    1993: -254948,
}

# Data from treasury_bulletin_1999_06_page_15.txt (1994-1999)
data_1999 = {
    1994: -203370,  # Using actual from 1994
    1995: -163813,
    1996: -107331,
    1997: -22618,
    1998: 70039,
}

# Data from treasury_bulletin_2004_06_page_18.txt (1999-2004)
data_2004 = {
    1999: 125974,
    2000: 236917,
    2001: 127401,
    2002: -157823,
    2003: -374791,
}

# Data from treasury_bulletin_2009_06_page_20.txt (2004-2009)
data_2009 = {
    2004: -412986,
    2005: -318298,
    2006: -248197,
    2007: -161527,
    2008: -454798,
}

# Data from treasury_bulletin_2014_06_page_19.txt (2009-2013)
data_2014 = {
    2009: -1415722,
    2010: -1294204,
    2011: -1295591,
    2012: -1089353,
    2013: -680276,
}

# Merge all data - later bulletins have more accurate final numbers
final_data = {}
for year in range(1989, 2014):
    final_data[year] = None

# Use earliest data for each year (they are revised over time)
for year, val in data_1994.items():
    if 1989 <= year <= 1993:
        final_data[year] = val

for year, val in data_1999.items():
    if 1994 <= year <= 1998:
        final_data[year] = val

for year, val in data_2004.items():
    if 1999 <= year <= 2003:
        final_data[year] = val

for year, val in data_2009.items():
    if 2004 <= year <= 2008:
        final_data[year] = val

for year, val in data_2014.items():
    if 2009 <= year <= 2013:
        final_data[year] = val

# Print the data
print("Calendar Year | Surplus/Deficit (millions USD)")
print("-" * 45)
for year in range(1989, 2014):
    print(f"{year} | {final_data[year]}")

print("\n\nData points:", len([v for v in final_data.values() if v is not None]))
