# Search ALL text in the bulletins for "2025 - Est" or similar patterns
import os, re

for root, dirs, files in os.walk('/app/resources'):
    for filename in files:
        if filename.endswith('.txt'):
            filepath = os.path.join(root, filename)
            try:
                with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
            except:
                continue

            # Look for patterns: "2025 - Est", "2025 Est", "2025 - Estimated"
            patterns = [
                r'2025\s*-\s*Est',
                r'2025\s*Est\.?',
                r'Est\.?\s*2025',
                r'2025.*?\$?\d{1,3}',  # 2025 followed by a number
            ]

            for pattern in patterns:
                matches = re.findall(pattern, content, re.IGNORECASE)
                if matches:
                    print(f"\n{filepath}: Pattern '{pattern}'")
                    # Get line context
                    lines = content.split('\n')
                    for i, line in enumerate(lines):
                        if re.search(pattern, line, re.IGNORECASE):
                            print(f"  {line[:200]}")
                            break
